"""
    Assigns the majority class label to each sentence for each task.
    Returns two lists: predicted AC and predicted SP
    """
def assign_labels(sentences: Any) -> object {
    predictions_category = [];
    predictions_sentiment = [];
    for sentence in sentences {
        prediction_cat = 'NA';
        predictions_category.append(prediction_cat);
        prediction_sent = 'Neutral';
        predictions_sentiment.append(prediction_sent);
    }
    return (predictions_category, predictions_sentiment);
}

test_blocks:
test "t0" {
    assert (assign_labels([["I", "enjoyed", "the", "movie"]]) == (["NA"], ["Neutral"]));;
}

test "t1" {
    assert (assign_labels([]) == ([], []));;
}

test "t2" {
    assert (
        assign_labels(
            [['This is a test sentence.'], ['This is another test sentence.']]
        )
        == (['NA', 'NA'], ['Neutral', 'Neutral'])
    );;
}

test "t3" {
    assert (assign_labels(`list()) == ([], []));;
}

test "t4" {
    assert (
        assign_labels(['The cat sat on the mat.', 'The dog sat on the log.'])
        == (['NA', 'NA'], ['Neutral', 'Neutral'])
    );;
}

test "t5" {
    assert (assign_labels(`list(['a', 'b'])) == (['NA', 'NA'], ['Neutral', 'Neutral']));;
}

test "t6" {
    assert (assign_labels(`list(['a'])) == (['NA'], ['Neutral']));;
}

test "t7" {
    assert (
        assign_labels(['The cake is a lie.', 'The movie is a drama.'])
        == (['NA', 'NA'], ['Neutral', 'Neutral'])
    );;
}

test "t8" {
    assert (assign_labels(['The cat sat on the mat.']) == (['NA'], ['Neutral']));;
}
